competition.sh_usage() {
  printf "competition.sh - Set up and manage a web development competition environment (Gitea, Traefik, MySQL, Verdaccio, WUD)\n\n"

  printf "%s\n" "Usage:"
  printf "  competition.sh [OPTIONS] COMMAND\n"
  printf "  competition.sh [COMMAND] --help | -h\n"
  printf "  competition.sh --version\n"
  echo

  printf "%s\n" "Commands:"
  printf "  %s   Install system dependencies (Docker, jq, git, curl, certbot...)\n" "setup            "
  printf "  %s   Check config/main.json and list every problem, without changing anything\n" "check-config     "
  printf "  %s   Initialize the environment from config/main.json and start every service\n" "init             "
  printf "  %s   Start all services\n" "start            "
  printf "  %s   Stop all services, keeping their containers and data\n" "stop             "
  printf "  %s   Recreate some services without touching the rest of the stack\n" "recreate         "
  printf "  %s   Re-import the frameworks templates into Gitea and cache their npm dependencies (after changing allowed_frameworks or the frameworks repository)\n" "import-frameworks"
  printf "  %s   Cache the npm dependencies of every framework template in Verdaccio, then cut npmjs off (also done by init)\n" "prefetch-npm     "
  printf "  %s   Turn Verdaccio's npm proxy on (any package) or off (cached packages only); without argument, show it\n" "npm-proxy        "
  printf "  %s   Deploy the enabled APIs of config/apis/ for every competitor (after adding, changing or disabling one)\n" "deploy-apis      "
  printf "  %s   Replace a competitor's API database by the initial SQLite database of the API\n" "reset-api        "
  printf "  %s   Back up data, config and .env into backups/ (services are stopped during the copy)\n" "backup           "
  printf "  %s   Replace the current environment with a backup (the current one is backed up first)\n" "restore          "
  printf "  %s   Remove every container, data, generated file and competitor image (a backup is made first)\n" "clean            "
  echo

  if [[ -n "$long_usage" ]]; then

    printf "%s\n" "Global Options:"

    printf "  %s\n" "--verbose, -v"
    printf "    Show debug output and the output of every underlying command\n"
    echo

    printf "  %s\n" "--help, -h"
    printf "    Show this help\n"
    echo
    printf "  %s\n" "--version"
    printf "    Show version number\n"
    echo

    printf "Every command must be run as root (sudo).\n"
    echo

  fi
}

