normalize_input() {
  local arg passthru flags
  passthru=false

  while [[ $# -gt 0 ]]; do
    arg="$1"
    if [[ $passthru == true ]]; then
      input+=("$arg")
    elif [[ $arg =~ ^(--[a-zA-Z0-9_\-]+)=(.+)$ ]]; then
      input+=("${BASH_REMATCH[1]}")
      input+=("${BASH_REMATCH[2]}")
    elif [[ $arg =~ ^(-[a-zA-Z0-9])=(.+)$ ]]; then
      input+=("${BASH_REMATCH[1]}")
      input+=("${BASH_REMATCH[2]}")
    elif [[ $arg =~ ^-([a-zA-Z0-9][a-zA-Z0-9]+)$ ]]; then
      flags="${BASH_REMATCH[1]}"
      for ((i = 0; i < ${#flags}; i++)); do
        input+=("-${flags:i:1}")
      done
    elif [[ "$arg" == "--" ]]; then
      passthru=true
      input+=("$arg")
    else
      input+=("$arg")
    fi

    shift
  done
}

# Native PHP APIs provided by the organizers, one container per API and competitor.
# Each API is a folder config/apis/<folder>/ (not versioned, except the template) with an api.json:
#   enabled        true/false, disabled APIs are ignored everywhere
#   name           used in container names (<username>_<name>) and data/apis/<name>/
#   host           host name without the domain, with {subdomain} and/or {username}, e.g. "{subdomain}-api"
#   document_root  folder served by Apache, relative to the API folder (default ".")
#   php_version    image php:<version>-apache (default "8.3")
#   sqlite         initial SQLite database, relative to the API folder, copied once per competitor (optional)
#   env            extra environment variables (optional)

APIS_DEFAULT_PHP_VERSION="8.3"
# Host names already used by the other services
APIS_RESERVED_HOSTS=(git npm wud pma db)

# Folders of the enabled APIs, one per line
enabled_apis() {
    local file
    for file in "$CONFIG_DIR"/apis/*/api.json; do
        [ -f "$file" ] || continue
        [ "$(jq -r '.enabled' "$file" 2> /dev/null)" = "true" ] && dirname "$file"
    done
}

# api_field <api folder> <jq filter>: print a field of the API's api.json
api_field() {
    jq -r "$2" "$1/api.json"
}

# Folder of the enabled API named <name>
api_dir_by_name() {
    local dir
    for dir in $(enabled_apis); do
        [ "$(api_field "$dir" .name)" = "$1" ] && echo "$dir" && return 0
    done
    return 1
}

# Host name (without the domain) of an API for a competitor
api_host() {
    local dir=$1 username=$2 subdomain=$3
    local host
    host=$(api_field "$dir" .host)
    host=${host//\{subdomain\}/$subdomain}
    echo "${host//\{username\}/$username}"
}

# Folder holding a competitor's writable copy of the API's SQLite database
api_data_dir() {
    echo "$DATA_DIR/apis/$1/$2"
}

# Copy the initial SQLite database for each competitor, unless it already exists (a redeploy keeps data).
# With --reset, existing copies are replaced. Apache runs as www-data (uid 33) and SQLite needs to write
# next to the database (journal), so the whole folder belongs to it.
prepare_api_data() {
    local dir=$1 only_user=${2:-} reset=${3:-false}
    local name sqlite username data_dir
    name=$(api_field "$dir" .name)
    sqlite=$(api_field "$dir" '.sqlite // empty')

    for username in $(jq -r '.competitors[].username' "$CONFIG_DIR/main.json"); do
        [ -n "$only_user" ] && [ "$username" != "$only_user" ] && continue
        data_dir=$(api_data_dir "$name" "$username")
        mkdir -p "$data_dir"
        if [ -n "$sqlite" ] && { [ "$reset" = true ] || [ ! -f "$data_dir/$(basename "$sqlite")" ]; }; then
            rm -rf "${data_dir:?}"/*
            cp "$dir/$sqlite" "$data_dir/"
        fi
        chown -R 33:33 "$data_dir"
    done
}

# Write the compose file of every enabled API for every competitor (removed when no API is enabled)
generate_apis_compose() {
    local file=$1
    local dirs dir name host php_version document_root sqlite env_json username subdomain service

    mapfile -t dirs < <(enabled_apis)
    if [ ${#dirs[@]} -eq 0 ]; then
        rm -f "$file"
        return
    fi

    mkdir -p "$(dirname "$file")"
    echo "services:" > "$file"
    for dir in "${dirs[@]}"; do
        name=$(api_field "$dir" .name)
        php_version=$(api_field "$dir" ".php_version // \"$APIS_DEFAULT_PHP_VERSION\"")
        document_root=$(api_field "$dir" '.document_root // "."')
        sqlite=$(api_field "$dir" '.sqlite // empty')
        # Extra variables, as YAML lines ("      KEY: "value""); "$" is doubled so compose keeps it as-is
        env_json=$(api_field "$dir" '(.env // {}) | to_entries[] | "      \(.key): \(.value | gsub("\\$"; "$$") | tojson)"')

        while IFS=$'\t' read -r username subdomain; do
            service="${username}_${name}"
            host="$(api_host "$dir" "$username" "$subdomain").$DOMAIN"
            cat <<EOF >> "$file"
  ${service}:
    image: php:${php_version}-apache
    container_name: ${service}
    restart: always
    command: ["sh", "/usr/local/bin/start-apache.sh"]
    networks:
      - gitea
    environment:
      APACHE_DOCUMENT_ROOT: /var/www/api/${document_root}
      API_NAME: ${name}
      COMPETITOR: ${username}
      DB_PATH: /var/www/data/$(basename "${sqlite:-database.sqlite}")
${env_json}
    volumes:
      - "${dir}:/var/www/api:ro"
      - "$(api_data_dir "$name" "$username"):/var/www/data"
      - "${SERVICES_DIR}/$(basename "$(service_dir apis)")/start-apache.sh:/usr/local/bin/start-apache.sh:ro"
    labels:
      competition.api: "${name}"
      wud.watch: "false"
      traefik.enable: "true"
      traefik.http.routers.${service}.rule: Host(\`${host}\`)
      traefik.http.routers.${service}.entrypoints: ${ENTRYPOINT}
      traefik.http.routers.${service}.tls: "${ENABLE_HTTPS}"
      traefik.http.routers.${service}.middlewares: ${service}-cors
      traefik.http.middlewares.${service}-cors.headers.accessControlAllowOriginList: "*"
      traefik.http.middlewares.${service}-cors.headers.accessControlAllowMethods: GET,POST,PUT,PATCH,DELETE,OPTIONS
      traefik.http.middlewares.${service}-cors.headers.accessControlAllowHeaders: "*"
      traefik.http.middlewares.${service}-cors.headers.addVaryHeader: "true"
      traefik.http.services.${service}.loadbalancer.server.port: 80
EOF
        done < <(jq -r '.competitors[] | [.username, .subdomain] | @tsv' "$CONFIG_DIR/main.json")
    done

    cat <<EOF >> "$file"

networks:
  gitea:
    external: true
EOF
}

# Remove API containers that are not in the compose file anymore (API disabled or deleted).
# Compose's --remove-orphans can't be used: every service shares the same compose project.
remove_stale_api_containers() {
    local file=$1
    local wanted container
    wanted=" $( [ -f "$file" ] && docker compose -f "$file" config --services 2> /dev/null | tr '\n' ' ') "
    for container in $(docker ps -a --filter label=competition.api --format '{{.Names}}'); do
        if [[ "$wanted" != *" $container "* ]]; then
            log_info "Removing $container (API disabled or removed)"
            docker rm -f "$container" > /dev/null
        fi
    done
}

# Print one line per problem in the api.json files (called by validate_configuration, main.json is valid)
validate_apis() {
    local file label
    for file in "$CONFIG_DIR"/apis/*/api.json; do
        [ -f "$file" ] || continue
        label="apis/$(basename "$(dirname "$file")")/api.json"
        if ! jq empty "$file" 2> /dev/null; then
            echo "$label: not valid JSON"
            continue
        fi
        jq -r --arg label "$label" '
            def text: type == "string" and length > 0;
            def check(cond; message): if cond then empty else "\($label): \(message)" end;
            check(.enabled | type == "boolean"; "enabled: must be true or false"),
            if .enabled != true then empty else
                check(.name | text and test("^[a-z0-9][a-z0-9-]*$");
                    "name: required, lowercase letters, digits and dashes only"),
                check(.host | text and test("^[a-z0-9{}-]+$") and test("\\{(subdomain|username)\\}")
                        and (gsub("\\{(subdomain|username)\\}"; "") | test("^[a-z0-9-]*$"));
                    "host: required, lowercase letters, digits, dashes and {subdomain} or {username} (e.g. \"{subdomain}-api\")"),
                check(.document_root | . == null or (text and (test("(^/|\\.\\.)") | not));
                    "document_root: must be a folder inside the API folder"),
                check(.php_version | . == null or (type == "string" and test("^[0-9]+\\.[0-9]+$"));
                    "php_version: must look like \"8.3\""),
                check(.sqlite | . == null or (text and (test("(^/|\\.\\.)") | not));
                    "sqlite: must be a file inside the API folder"),
                check(.env | . == null or (type == "object" and all(.[]; type == "string")
                        and all(keys[]; test("^[A-Za-z_][A-Za-z0-9_]*$")));
                    "env: must be an object of string values with valid variable names")
            end
        ' "$file"

        # Files referenced by an enabled API must exist
        if [ "$(jq -r '.enabled' "$file")" = "true" ]; then
            local dir document_root sqlite
            dir=$(dirname "$file")
            document_root=$(jq -r '.document_root // "."' "$file")
            sqlite=$(jq -r '.sqlite // empty' "$file")
            [ -d "$dir/$document_root" ] || echo "$label: document_root: folder \"$document_root\" not found"
            [ -z "$sqlite" ] || [ -f "$dir/$sqlite" ] || echo "$label: sqlite: file \"$sqlite\" not found"
        fi
    done

    # Names and host names must not collide between APIs, modules and the other services
    local apis_json
    apis_json=$(for file in "$CONFIG_DIR"/apis/*/api.json; do
        [ -f "$file" ] && jq -c 'select(.enabled == true and (.name | type) == "string" and (.host | type) == "string")
            | {name, host}' "$file" 2> /dev/null
    done | jq -s '.')
    jq -r --argjson apis "$apis_json" --argjson reserved "$(printf '%s\n' "${APIS_RESERVED_HOSTS[@]}" | jq -R . | jq -s .)" '
        def duplicates: group_by(.) | map(select(length > 1) | .[0]) | .[];
        .modules as $modules
        | ($apis | map(.name) | duplicates | "apis: name \"\(.)\" is used by several enabled APIs"),
          ($apis[] | .name as $n | select($modules | index($n)) | "apis: name \"\($n)\" is also a module name"),
          ([(.competitors[] as $c
             | ($modules[] | "\($c.subdomain)-\(.)"),
               ($apis[] | .host | gsub("\\{subdomain\\}"; $c.subdomain) | gsub("\\{username\\}"; $c.username))),
            $reserved[]
           ] | duplicates | "apis: host \"\(.)\" is used more than once (modules, APIs or other services)")
    ' "$CONFIG_DIR/main.json"
}

# Everything needed to bring an environment back, relative to $BASE_DIR.
# Competitor images live in Gitea's container registry, so they are inside data/gitea.
BACKUP_ITEMS=(data config dynamic/docker dynamic/dashboard dynamic/portal .env competition.lock)

# Write the given items (relative to $BASE_DIR) into a root-only archive.
# --numeric-owner: keep container uids (mysql 999, gitea 1000, verdaccio 10001) even if the host maps
# those numbers to other names or the backup is restored on another machine
write_archive() {
    local file=$1
    shift
    (umask 077 && tar --numeric-owner -czpf "$file" -C "$BASE_DIR" "$@")
}

# Create a tar.gz of BACKUP_ITEMS in $BACKUP_DIR. Services must be stopped for a consistent MySQL copy.
# Sets LAST_BACKUP_FILE (empty when there was nothing to back up).
create_backup_archive() {
    local label=${1:-manual}
    local items=() item
    LAST_BACKUP_FILE=""

    for item in "${BACKUP_ITEMS[@]}"; do
        [ -e "$BASE_DIR/$item" ] && items+=("$item")
    done

    if [ ! -d "$DATA_DIR" ]; then
        log_warning "No data directory, nothing to back up"
        return 0
    fi

    # Archives contain .env, Gitea and MySQL data: readable by root only
    mkdir -p "$BACKUP_DIR"
    chmod 700 "$BACKUP_DIR"
    LAST_BACKUP_FILE="$BACKUP_DIR/backup-$(date +%Y%m%d-%H%M%S)-$label.tar.gz"

    if ! run_with_spinner "Creating $LAST_BACKUP_FILE..." write_archive "$LAST_BACKUP_FILE" "${items[@]}"; then
        rm -f "$LAST_BACKUP_FILE"
        return 1
    fi
    log_success "Backup created ($(du -h "$LAST_BACKUP_FILE" | cut -f1)): $LAST_BACKUP_FILE"
}

list_backups() {
    echo "Available backups in $BACKUP_DIR:"
    ls -1t "$BACKUP_DIR"/backup-*.tar.gz 2>/dev/null | xargs -r -n1 basename | sed 's/^/  /'
}

# Print the archive path for a file path, a file name in $BACKUP_DIR, or "latest"
resolve_backup() {
    local name=$1
    if [ "$name" = "latest" ]; then
        ls -1t "$BACKUP_DIR"/backup-*.tar.gz 2>/dev/null | head -n1
    elif [ -f "$name" ]; then
        realpath "$name"
    elif [ -f "$BACKUP_DIR/$(basename "$name")" ]; then
        echo "$BACKUP_DIR/$(basename "$name")"
    fi
}

# Remove every container, data, generated file and competitor image.
# With do_backup=true (default), a backup is made once the services are down; if it fails nothing is deleted.
clean_environment() {
    local do_backup=${1:-true}

    load_configuration

    log_section "Cleaning Competition Environment"

    log_subsection "Stopping Docker Services"
    compose_each --reverse down -v
    log_success "Docker services stopped"

    # Services are down at this point, so the copy is consistent
    if [ "$do_backup" = true ]; then
        log_subsection "Backing up before removing anything"
        if ! create_backup_archive "clean"; then
            log_error "Backup failed, nothing was deleted. Use --no-backup to clean anyway."
            exit 1
        fi
    else
        log_warning "Skipping backup (--no-backup)"
    fi

    log_subsection "Removing Data Volumes"
    rm -rf "$DATA_DIR"
    log_success "Data volumes removed"

    local name
    for name in $(service_names_reversed); do
        run_service_hook "$name" clean
    done

    log_subsection "Cleaning up Dynamic Directories"
    rm -rf "$DYNAMIC_DOCKER_DIR"
    rm -rf "$DYNAMIC_DASHBOARD_DIR"
    rm -rf "$DYNAMIC_PORTAL_DIR"
    rm -rf "$DYNAMIC_FRAMEWORKS_DIR"
    rm -f "$LOCK_FILE"
    log_success "Dynamic directories cleaned"

    echo ""
    log_success "Clean complete! Environment reset. 🧹"
}

# Initialize competitors compose file
initialize_competitors_config() {
    log_info "Initializing competitors configuration..."

    cat <<EOF > $DYNAMIC_DOCKER_DIR/competitors.yaml
services:
EOF
}

# Add competitor module to Docker Compose configuration
add_competitor_module_to_compose() {
    local user=$1
    local module=$2
    local subdomain=$3

    cat <<EOF >> $DYNAMIC_DOCKER_DIR/competitors.yaml
  ${user}_${module}:
    image: git.${DOMAIN}/${user}/${module}:1.0.0
    container_name: ${user}_${module}
    restart: always
    networks:
      - gitea
    labels:
      - "wud.watch=true"
      - "wud.watch.digest=true"
      - "wud.registry=gitea.private"
      - 'wud.tag.include=^\d+\.\d+\.\d+\$\$'
      - "traefik.enable=true"
      - "traefik.http.routers.${user}_${module}.rule=Host(\`${subdomain}-${module}.$DOMAIN\`)"
      - "traefik.http.routers.${user}_${module}.entrypoints=${ENTRYPOINT}"
      - "traefik.http.routers.${user}_${module}.tls=${ENABLE_HTTPS}"
      - "traefik.http.services.${user}_${module}.loadbalancer.server.port=80"
EOF
}

# Push initial container image for competitor module
push_initial_module_image() {
    local user=$1
    local module=$2

    log_debug "Pushing initial container for $user/$module"
    docker tag nginx:latest git.$DOMAIN/$user/$module:1.0.0
    docker tag nginx:latest git.$DOMAIN/$user/$module:latest

    run_with_spinner "Pushing initial image for $user/$module..." \
        docker push --all-tags git.$DOMAIN/$user/$module
}

# Process a single competitor module
process_competitor_module() {
    local user=$1
    local module=$2
    local subdomain=$3

    log_debug "Processing module: $module for $user"

    add_competitor_module_to_compose "$user" "$module" "$subdomain"
    push_initial_module_image "$user" "$module"
}

# Process a single competitor
process_competitor() {
    local name=$1
    local username=$2
    local password=$3
    local subdomain=$4

    log_subsection "Competitor: $name (subdomain: $subdomain)"

    create_competitor_user "$username" "$password"
    add_competitor_to_team "frameworks" "competitors" "$username"
    create_user_secrets "$username" "$password"

    for module in $MODULES; do
        process_competitor_module "$username" "$module" "$subdomain"
    done
}

# Process all competitors from configuration file ("name" is optional, the username is shown instead)
process_all_competitors() {
    local config_file=$1
    local name username password subdomain

    log_section "Processing All Competitors"

    while IFS=$'\t' read -r name username password subdomain; do
        process_competitor "$name" "$username" "$password" "$subdomain"
    done < <(jq -r '.competitors[] | [.name // .username, .username, .password, .subdomain] | @tsv' "$config_file")
}

# Finalize Docker Compose configuration
finalize_docker_compose_config() {
    cat <<EOF >> $DYNAMIC_DOCKER_DIR/competitors.yaml

networks:
  gitea:
    external: true
EOF
}

# Load and export configuration from main.json
load_configuration() {
    local config_file=$CONFIG_DIR/main.json
    log_debug "Loading configuration from $config_file"

    export DOMAIN=$(jq -r '.domain' "$config_file")
    export ENABLE_HTTPS=$(jq -r '.enable_https' "$config_file")
    export USERNAME=$(jq -r '.username' "$config_file")
    export PASSWORD=$(jq -r '.password' "$config_file")
    export MODULES=$(jq -r '.modules | join(" ")' "$config_file")
    export FRAMEWORKS_REPO=$(jq -r '.frameworks.frameworks_repo' "$config_file")
    export ALLOWED_FRAMEWORKS=$(jq -r '.frameworks.allowed_frameworks | join(" ")' "$config_file")
}

# Setup HTTP/HTTPS related variables
setup_protocol_vars() {
    if [ "$ENABLE_HTTPS" = "true" ]; then
        export ENTRYPOINT=websecure
        export GITEA_PROTOCOL=https
        export REGISTRY_PORT=443
    else
        export ENTRYPOINT=web
        export GITEA_PROTOCOL=http
        export REGISTRY_PORT=5000
    fi
}

# Setup service hostnames and credentials
setup_service_vars() {
    export GITEA_HOSTNAME=$DOMAIN
    export MYSQL_ROOT_PASSWORD=$PASSWORD
    export GITEA_URL="$GITEA_PROTOCOL://git.$DOMAIN"
}

# Setup directory variables
setup_directory_vars() {
    mkdir -p ${DYNAMIC_DOCKER_DIR} ${DYNAMIC_FRAMEWORKS_DIR}
    export CONFIG_FILE=$CONFIG_DIR/main.json
}

# Main configuration initialization
initialize_configuration() {
    log_section "Initializing Configuration"
    load_configuration
    log_debug "Loaded configuration from main.json"
    setup_protocol_vars
    log_debug "Setup protocol variables (HTTPS: $ENABLE_HTTPS)"
    setup_service_vars
    log_debug "Setup service variables"
    setup_directory_vars
    log_debug "Setup directory variables"
    touch "$LOCK_FILE"
    log_success "Configuration initialized"
}

# Print one line per problem in config/main.json (nothing when it is valid).
# Usernames, subdomains and modules end up in DNS names, container names, image paths and database
# names; passwords are inserted as-is in SQL and JSON (quotes and backslashes would break them) and read
# back as tab-separated values (tabs and other control characters would be mangled).
validate_configuration() {
    local config_file=$CONFIG_DIR/main.json

    if [ ! -f "$config_file" ]; then
        echo "$config_file not found"
        return
    fi
    if ! jq empty "$config_file" 2> /dev/null; then
        echo "not valid JSON: $(jq empty "$config_file" 2>&1 | head -n1)"
        return
    fi

    jq -r '
        def text: type == "string" and length > 0;
        def name: text and test("^[a-z0-9][a-z0-9-]*$");
        def password: text and (test("[\"'"'"'\\\\[:cntrl:]]") | not);
        def check(cond; message): if cond then empty else message end;
        def duplicates(f): [.[] | f] | group_by(.) | map(select(length > 1) | .[0]) | .[];

        check(.domain | text; "domain: required (e.g. \"local.skill17.com\")"),
        check(.enable_https | type == "boolean"; "enable_https: must be true or false"),
        check(.username | name; "username: required, lowercase letters, digits and dashes only"),
        check(.password | password; "password: required, without quotes, backslashes or control characters (tab...)"),
        check(.modules | type == "array" and length > 0 and all(.[]; name);
            "modules: required, a non-empty list of names (lowercase letters, digits and dashes)"),
        check(.frameworks.frameworks_repo | text; "frameworks.frameworks_repo: required (git URL)"),
        check(.frameworks.allowed_frameworks | . == null or (type == "array" and all(.[]; text));
            "frameworks.allowed_frameworks: must be a list of framework names"),

        if (.competitors | type == "array" and length > 0) | not then
            "competitors: required, a non-empty list"
        else
            (.competitors | to_entries[] | .key as $i | .value |
                check(.username | name; "competitors[\($i)].username: required, lowercase letters, digits and dashes only"),
                check(.password | password; "competitors[\($i)].password: required, without quotes, backslashes or control characters (tab...)"),
                check(.subdomain | name; "competitors[\($i)].subdomain: required, lowercase letters, digits and dashes only"),
                check(.name | . == null or text; "competitors[\($i)].name: must be a non-empty string if set")),
            (.competitors | duplicates(.username) | "competitors: username \"\(.)\" is used more than once"),
            (.competitors | duplicates(.subdomain) | "competitors: subdomain \"\(.)\" is used more than once")
        end
    ' "$config_file"

    # The api.json files are checked once main.json is valid (their host names depend on it)
    local main_errors
    main_errors=$(jq -r '.competitors | type' "$config_file")
    [ "$main_errors" = "array" ] && validate_apis
}

# Save the values computed by init to .env. Paths are not saved: initialize.sh derives them from the
# script location, so the project can be moved or restored elsewhere.
export_environment_variables() {
    local output_file=${1:-$BASE_DIR/.env}

    log_info "Exporting environment variables to $output_file"

    cat <<EOF > "$output_file"
DOMAIN="$DOMAIN"
ENABLE_HTTPS="$ENABLE_HTTPS"
USERNAME="$USERNAME"
PASSWORD="$PASSWORD"
MODULES="$MODULES"
GITEA_HOSTNAME="$GITEA_HOSTNAME"
MYSQL_ROOT_PASSWORD="$MYSQL_ROOT_PASSWORD"
ENTRYPOINT="$ENTRYPOINT"
GITEA_PROTOCOL="$GITEA_PROTOCOL"
REGISTRY_PORT="$REGISTRY_PORT"
GITEA_URL="$GITEA_URL"
GITEA_TOKEN="$GITEA_TOKEN"
REGISTRATION_TOKEN="$REGISTRATION_TOKEN"
EOF
}

# Paths derived from $BASE_DIR (the script location)
set_paths() {
    export BASE_DIR
    export CONFIG_DIR=$BASE_DIR/config
    export SERVICES_DIR=$BASE_DIR/services
    export DATA_DIR=$BASE_DIR/data
    export BACKUP_DIR=$BASE_DIR/backups
    export LOCK_FILE=$BASE_DIR/competition.lock
    # Generated files
    export DYNAMIC_DOCKER_DIR=$BASE_DIR/dynamic/docker
    export DYNAMIC_FRAMEWORKS_DIR=$BASE_DIR/dynamic/frameworks
    export DYNAMIC_DASHBOARD_DIR=$BASE_DIR/dynamic/dashboard
    export DYNAMIC_PORTAL_DIR=$BASE_DIR/dynamic/portal
}

# Load .env, then set the paths again: .env files written by older versions (and old backups) still
# contain absolute paths, which must not override the current location
load_env_file() {
    local base_dir=$BASE_DIR
    if [ -f "$base_dir/.env" ]; then
        set -a
        # shellcheck disable=SC1091
        source "$base_dir/.env"
        set +a
    fi
    BASE_DIR=$base_dir
    set_paths

    if [ -n "$DOMAIN" ]; then
        export GITEA_URL=${GITEA_URL:-"$GITEA_PROTOCOL://git.$DOMAIN"}
    fi
}

# Bashly filters: printing a message stops the command with that error

# Data files belong to container users (root, mysql 999, gitea 1000, verdaccio 10001), so every command
# runs as root: init creates them, backup/clean read them, restore gives them back their owners.
filter_root() {
    [ "$EUID" -eq 0 ] || echo "This command must be run as root: sudo $0 ..."
}

filter_initialized() {
    [ -f "$LOCK_FILE" ] || echo "Competition is not initialized. Please run the 'init' command first."
}

filter_not_initialized() {
    [ ! -f "$LOCK_FILE" ] || echo "Competition is already initialized. To re-initialize, please run the 'clean' command first."
}

filter_valid_config() {
    local errors
    errors=$(validate_configuration)
    if [ -n "$errors" ]; then
        printf 'Invalid config/main.json:\n%s\n' "$(sed 's/^/  - /' <<< "$errors")"
    fi
}

# Import a framework from a local path
import_framework() {
    local framework_path=$1
    local framework_name=$2

    # Check if .npmrc exists and replace ##DOMAIN## with actual domain
    if [ -f "$framework_path/.npmrc" ]; then
        log_info "Found .npmrc in $framework_name, replacing ##DOMAIN## with $DOMAIN"
        sed -i "s/##DOMAIN##/$DOMAIN/g" "$framework_path/.npmrc"
        log_info ".npmrc updated with domain: $DOMAIN"
    fi

    push_framework_repo "$framework_path" "$framework_name"
}

# Create (or update) the template repository <name> in the "frameworks" organization from a local folder.
# Runs in a subshell: it changes directory and may exit early.
push_framework_repo() (
    local repo_path=$1
    local repo_name=$2
    local org_name='frameworks'
    local host="git.${DOMAIN}"
    local remote_url="https://$USERNAME:$PASSWORD@$host/$org_name/$repo_name.git"

    cd "$repo_path" || exit 1

    local repo_status
    repo_status=$(curl -s -k -o /dev/null -w '%{http_code}' -H "Authorization: token $GITEA_TOKEN" "https://$host/api/v1/repos/$org_name/$repo_name")

    if [ "$repo_status" = "200" ]; then
        # The template already exists: commit the new content on top of its history instead of recreating it,
        # so repositories generated from it keep their link and nothing is force-pushed.
        echo "Repository $repo_name already exists, updating it..."
        rm -rf .git
        local tmp_clone
        tmp_clone=$(mktemp -d)
        if ! git -c http.sslVerify=false clone --quiet --no-checkout "$remote_url" "$tmp_clone" > $REDIRECT 2>&1; then
            rm -rf "$tmp_clone"
            echo "Failed to clone $org_name/$repo_name from Gitea"
            exit 1
        fi
        mv "$tmp_clone/.git" .git
        rm -rf "$tmp_clone"
        git config user.name "Init Bot"
        git config user.email "init-bot@$DOMAIN"
        git config http.sslVerify false

        git add -A
        if git diff --cached --quiet; then
            echo "Repository $repo_name is already up to date."
            exit 0
        fi
        git commit -m "Update framework" > $REDIRECT 2>&1
        git push origin HEAD > $REDIRECT 2>&1 || {
            echo "Failed to push $repo_name to Gitea"
            exit 1
        }
        echo "Repository $repo_name updated in the $org_name organization !"
        exit 0
    fi

    echo "Configuring git repository..."
    git init -b main > $REDIRECT 2>&1
    git config user.name "Init Bot"
    git config user.email "init-bot@$DOMAIN"
    git config http.sslVerify false

    echo "Commiting changes..."
    git add -A
    git commit -m "Initial commit" > $REDIRECT 2>&1

    echo "Creating the repository on Gitea"
    local create_repo_response
    create_repo_response=$(curl -s -k -X POST "https://$host/api/v1/orgs/$org_name/repos" \
        -H "Authorization: token $GITEA_TOKEN" \
        -H "Content-Type: application/json" \
        -d '{
          "name": "'"$repo_name"'",
          "private": false,
          "template": true
        }')

    if echo "$create_repo_response" | grep -q '"id":'; then
        echo "Repository $repo_name created in the $org_name organization on Gitea."
    else
        echo "Failed to create repository on Gitea: $create_repo_response"
        exit 1
    fi

    echo "Pushing the repository to Gitea..."
    git remote remove gitea 2>/dev/null
    git remote add gitea "$remote_url"
    git push -u gitea main --force > $REDIRECT 2>&1

    echo "Repository $repo_name pushed to the $org_name organization !"
)

# Setup Docker credentials for registry
setup_docker_registry_credentials() {
    log_info "Setting up Docker registry credentials..."

    run_with_spinner "Pulling nginx image..." docker pull nginx:latest
    docker login -u $USERNAME -p $PASSWORD git.$DOMAIN > /dev/null 2>&1
    log_success "Docker registry credentials configured"
}

# Clone and process frameworks repository, importing only allowed frameworks
import_all_frameworks() {
    log_section "Importing Frameworks"

    if [ -z "$ALLOWED_FRAMEWORKS" ]; then
        log_warning "No allowed_frameworks configured, importing all frameworks"
    fi

    rm -rf "$DYNAMIC_FRAMEWORKS_DIR"
    run_with_spinner "Cloning frameworks repository..." git clone "$FRAMEWORKS_REPO" "$DYNAMIC_FRAMEWORKS_DIR" || exit 1

    cd "$DYNAMIC_FRAMEWORKS_DIR" || exit 1
    rm -rf "$DYNAMIC_FRAMEWORKS_DIR/.git"

    local imported=() failed=()
    for dir in */; do
        [ -d "$dir" ] || continue
        framework_name=$(basename "$dir")

        # Skip frameworks not in the allow list (exact, case-sensitive match)
        if [ -n "$ALLOWED_FRAMEWORKS" ] && [[ " $ALLOWED_FRAMEWORKS " != *" $framework_name "* ]]; then
            log_info "Skipping $framework_name (not in allowed_frameworks)"
            continue
        fi

        framework_path=$(realpath "$dir")
        log_subsection "Framework: $framework_name"
        if run_with_spinner "Importing $framework_name..." import_framework "$framework_path" "$framework_name"; then
            log_success "$framework_name imported"
            imported+=("$framework_name")
        else
            failed+=("$framework_name")
        fi
    done

    # Warn about allowed frameworks that don't exist in the repository
    for allowed in $ALLOWED_FRAMEWORKS; do
        [[ " ${imported[*]} ${failed[*]} " == *" $allowed "* ]] || log_warning "Allowed framework '$allowed' not found in repository"
    done

    log_success "Imported ${#imported[@]} framework(s): ${imported[*]}"
    [ ${#failed[@]} -eq 0 ] || log_error "Failed: ${failed[*]}"
    cd - > /dev/null
    [ ${#failed[@]} -eq 0 ]
}

# Create admin user in Gitea
create_admin_user() {
    local username=$1
    local password=$2

    log_info "Creating Gitea admin user: $username"
    docker exec gitea su -c "/app/gitea/gitea admin user create --username $username --password $password --email $username@example.com --admin" git
}

# Generate registration token for Gitea runner
generate_registration_token() {
    log_info "Generating registration token for Gitea runner..."
    local token=$(docker exec gitea su -c '/app/gitea/gitea actions generate-runner-token' git)
    export REGISTRATION_TOKEN=$token
    log_success "Registration Token: $REGISTRATION_TOKEN"
}

# Create organization in Gitea
create_organization() {
    local org_name=$1

    log_info "Creating organization: $org_name"
    curl -s -k -X POST "$GITEA_URL/api/v1/orgs" \
        -H "Content-Type: application/json" \
        -H "Authorization: token $GITEA_TOKEN" \
        -d "{
            \"username\": \"$org_name\",
            \"full_name\": \"$org_name\"
        }" > /dev/null
}

# Create a personal access token for the admin and print it. Gitea refuses two tokens with the same name.
create_pat() {
    local token_name=${1:-CreateOrganizationScript}
    local response new_token

    response=$(curl -s -k -X POST -H "Content-Type: application/json" \
        -u "$USERNAME:$PASSWORD" \
        -d '{
              "name": "'"$token_name"'",
              "scopes": ["read:admin","write:organization,write:repository,write:user"]
            }' \
        "$GITEA_URL/api/v1/users/$USERNAME/tokens")

    new_token=$(echo "$response" | grep -o '"sha1":"[^"]*"' | sed 's/"sha1":"//;s/"//g')
    if [ -z "$new_token" ] || [ "$new_token" == "null" ]; then
        echo "Failed to create token. Response: $response"
        return 1
    fi
    echo "$new_token"
}

# Returns 0 if $GITEA_TOKEN is accepted by Gitea
gitea_token_is_valid() {
    [ -n "$GITEA_TOKEN" ] || return 1
    [ "$(curl -s -k -o /dev/null -w '%{http_code}' -H "Authorization: token $GITEA_TOKEN" "$GITEA_URL/api/v1/user")" = "200" ]
}

# Use the token stored in .env by init. Installations made before it was stored get a new one,
# under a unique name (Gitea refuses duplicate names), saved to .env so this only happens once.
load_personal_access_token() {
    local env_file=$1
    gitea_token_is_valid && return 0

    log_warning "No valid GITEA_TOKEN in $env_file, creating a new one"
    export GITEA_TOKEN=$(create_pat "competition-scripts-$(date +%Y%m%d%H%M%S)")
    if ! gitea_token_is_valid; then
        log_error "Could not get a Gitea access token: $GITEA_TOKEN"
        return 1
    fi
    sed -i '/^GITEA_TOKEN=/d' "$env_file"
    echo "GITEA_TOKEN=\"$GITEA_TOKEN\"" >> "$env_file"
    log_success "Token saved to $env_file"
}

# Create user-level action secret
create_user_secret() {
    local user=$1
    local pass=$2
    local secret_name=$3
    local secret_value=$4

    curl -s -k -X PUT \
        -u "$user:$pass" \
        -H "Content-Type: application/json" \
        -d "{\"data\": \"$secret_value\"}" \
        "$GITEA_URL/api/v1/user/actions/secrets/$secret_name" > /dev/null
}

# Create all standard secrets for a user
create_user_secrets() {
    local user=$1
    local pass=$2

    log_info "Creating user-level secrets for $user..."

    create_user_secret "$user" "$pass" "USER" "$user"
    create_user_secret "$user" "$pass" "PASS" "$pass"
    create_user_secret "$user" "$pass" "DOMAIN" "$DOMAIN"
    create_user_secret "$user" "$pass" "NPM_REGISTRY_URL" "http://verdaccio:4873"
    create_user_secret "$user" "$pass" "SERVER_IP" "127.0.0.1"
}

# Create competitor user in Gitea
create_competitor_user() {
    local username=$1
    local password=$2

    log_info "Creating Gitea user: $username"
    docker exec gitea su -c "/app/gitea/gitea admin user create --username '$username' --password '$password' --email '$username@example.com' --must-change-password=false" git
}

# Add user to team
add_competitor_to_team() {
    local org=$1
    local team=$2
    local user=$3

    local team_id response

    team_id=$(curl -k -s -H "Authorization: token $GITEA_TOKEN" "$GITEA_URL/api/v1/orgs/$org/teams/search?q=$team" \
        | awk -F'"id":' '{print $2}' | awk -F',' '{print $1}' | head -n 1)
    if [ -z "$team_id" ] || [ "$team_id" == "null" ]; then
        log_error "Failed to retrieve team ID for team '$team' in organization '$org'."
        return 1
    fi

    response=$(curl -k -s -o /dev/null -w "%{http_code}" -X PUT \
        -H "Content-Type: application/json" \
        -H "Authorization: token $GITEA_TOKEN" \
        "$GITEA_URL/api/v1/teams/$team_id/members/$user")
    if [ "$response" -ne 204 ]; then
        log_error "Failed to add user '$user' to team '$team' in organization '$org'. HTTP status code: $response"
        return 1
    fi
    log_info "User '$user' added to team '$team' in organization '$org'."
}

# Create a team in an organization
create_team() {
    local org=$1
    local team=$2
    local can_create_org_repo=$3
    local response team_id

    response=$(curl -k -s -X POST -H "Content-Type: application/json" \
        -H "Authorization: token $GITEA_TOKEN" \
        -d '{
              "name": "'"$team"'",
              "can_create_org_repo": '"$can_create_org_repo"',
              "units_map": {
                "repo.actions": "read",
                "repo.packages": "none",
                "repo.code": "write",
                "repo.issues": "write",
                "repo.ext_issues": "none",
                "repo.wiki": "admin",
                "repo.pulls": "owner",
                "repo.releases": "none",
                "repo.projects": "none",
                "repo.ext_wiki": "none"
              }
            }' \
        "$GITEA_URL/api/v1/orgs/$org/teams")

    team_id=$(echo "$response" | awk -F'"id":' '{print $2}' | awk -F',' '{print $1}')
    if [ -z "$team_id" ] || [ "$team_id" == "null" ]; then
        log_error "Failed to create team. Response: $response"
        return 1
    fi
    log_info "Created team '$team' (ID: $team_id)"
}

# Setup basic organizations and teams
setup_organizations_and_teams() {
    log_section "Setting up Organizations and Teams"

    create_organization "images"
    create_organization "frameworks"

    create_team "frameworks" "competitors" false
}

# Color definitions
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
MAGENTA='\033[0;35m'
BOLD='\033[1m'
NC='\033[0m' # No Color

# Log functions
log_info() {
    echo -e "${BLUE}ℹ${NC}  $*"
}

log_success() {
    echo -e "${GREEN}✓${NC}  $*"
}

log_error() {
    echo -e "${RED}✗${NC}  $*" >&2
}

log_warning() {
    echo -e "${YELLOW}⚠${NC}  $*"
}

log_section() {
    echo ""
    echo -e "${BOLD}${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo -e "${BOLD}${CYAN}▶  $*${NC}"
    echo -e "${BOLD}${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
}

log_subsection() {
    echo -e "${BOLD}${MAGENTA}→  $*${NC}"
}

log_debug() {
    if [ "$VERBOSE" = true ]; then
        echo -e "${CYAN}🔍  $*${NC}"
    fi
}

# Spinner for long-running operations
show_spinner() {
    local pid=$1
    local message=$2
    local delay=0.1
    local spinner=( '⠋' '⠙' '⠹' '⠸' '⠼' '⠴' '⠦' '⠧' '⠇' '⠏' )

    while kill -0 $pid 2>/dev/null; do
        for i in "${spinner[@]}"; do
            echo -ne "\r${CYAN}$i${NC}  ${message}"
            sleep $delay
        done
    done
    echo -ne "\r\033[K"
}

# Run a command (or function) behind a spinner. Its output is hidden, and printed only if it fails.
# In verbose mode, or when the output is not a terminal, the output is shown directly instead.
run_with_spinner() {
    local message=$1
    shift

    if [ "$VERBOSE" = true ] || [ ! -t 1 ]; then
        log_info "$message"
        "$@"
        return
    fi

    local output pid status
    output=$(mktemp)
    "$@" > "$output" 2>&1 &
    pid=$!
    # Background jobs ignore Ctrl+C in scripts: stop it ourselves
    trap 'kill $pid 2>/dev/null; echo -ne "\r\033[K"; rm -f "$output"; exit 130' INT TERM
    show_spinner $pid "$message"
    wait $pid
    status=$?
    trap - INT TERM

    if [ $status -ne 0 ]; then
        log_error "$message (failed)"
        cat "$output" >&2
    fi
    rm -f "$output"
    return $status
}

# Recreate services individually, without touching the rest of the stack

# Maps "service name" -> "compose file"
declare -gA SERVICE_FILE
# Maps "group name" (service name) -> "compose file"
declare -gA GROUP_FILE

build_service_map() {
    local name file svc
    for name in $(service_names); do
        file=$(service_compose_file "$name")
        [ -f "$file" ] || continue
        GROUP_FILE[$name]=$file
        for svc in $(docker compose -f "$file" config --services 2>/dev/null < /dev/null); do
            SERVICE_FILE[$svc]=$file
        done
    done
}

print_available() {
    echo "Available services:"
    local name file
    for name in $(service_names); do
        file=$(service_compose_file "$name")
        [ -f "$file" ] || continue
        echo -n "  $name: "
        docker compose -f "$file" config --services 2>/dev/null | tr '\n' ' '
        echo ""
    done
    echo ""
    echo "A group name (e.g. 'mysql', 'runners', 'competitors') recreates every container of that service."
    echo "An exact service name always takes precedence over a group name (e.g. 'gitea' only recreates the gitea container)."
}

# Remove a container that holds the service's container_name but is no longer tracked by compose
# (e.g. a competitor container redeployed by WUD), otherwise "up" fails with a name conflict.
remove_untracked_container() {
    local file=$1 svc=$2
    local name
    name=$(docker compose -f "$file" config --format json 2>/dev/null | jq -r --arg s "$svc" '.services[$s].container_name // empty')
    [ -n "$name" ] || return 0
    docker container inspect "$name" > /dev/null 2>&1 || return 0
    if [ -z "$(docker compose -f "$file" ps -a -q "$svc" 2>/dev/null)" ]; then
        log_warning "Container '$name' exists but is not tracked by compose, removing it"
        docker rm -f "$name" > /dev/null
    fi
}

recreate_service() {
    local file=$1 svc=$2
    local files=(-f "$file")
    local override=""

    log_subsection "$svc"

    # Competitor images are bumped by WUD after the initial 1.0.0; keep the image currently running
    # instead of rolling the competitor back to the tag written in competitors.yaml.
    if [ "$file" = "$(service_compose_file competitors)" ]; then
        local running wanted
        running=$(docker inspect "$svc" --format '{{.Config.Image}}' 2>/dev/null)
        wanted=$(docker compose -f "$file" config --format json | jq -r --arg s "$svc" '.services[$s].image')
        if [ -n "$running" ] && [ "$running" != "$wanted" ]; then
            log_info "Keeping currently deployed image $running (compose file says $wanted)"
            override=$(mktemp --suffix=.yaml)
            printf 'services:\n  %s:\n    image: %s\n' "$svc" "$running" > "$override"
            files+=(-f "$override")
        fi
    fi

    run_service_hook "$(service_name_for_file "$file")" pre_up
    remove_untracked_container "$file" "$svc"
    docker compose "${files[@]}" up -d --no-deps --force-recreate "$svc"
    local status=$?
    [ -n "$override" ] && rm -f "$override"
    return $status
}

# Services live in services/<NN>-<name>/:
#   - NN is the start order (stop/down go in reverse order)
#   - compose.yaml is the service's compose file
#   - service.sh (optional) defines hooks named service_<name>_<hook>, loaded by initialize.sh:
#       compose_file  print the compose file path (default: the service's compose.yaml)
#       pre_init      init only, before the first "docker compose up" (generate files, prepare data dirs)
#       pre_up        before every "docker compose up" (init, restore, recreate): files the containers mount
#       wait_ready    after "docker compose up" (init, restore): return once the service answers
#       post_init     init only, once the service is ready (create users, import data...)
#       clean         clean only, after the containers are removed

# Service names in start order
service_names() {
    local dir
    for dir in "$SERVICES_DIR"/[0-9]*-*/; do
        [ -d "$dir" ] || continue
        dir=$(basename "$dir")
        echo "${dir#*-}"
    done
}

service_names_reversed() {
    service_names | tac
}

service_dir() {
    local dir
    for dir in "$SERVICES_DIR"/[0-9]*-"$1"/; do
        [ -d "$dir" ] && echo "${dir%/}" && return 0
    done
    return 1
}

# Call service_<name>_<hook> with the remaining arguments, if the service defines it
run_service_hook() {
    local name=$1 hook=$2
    shift 2
    local fn="service_${name//-/_}_${hook}"
    if declare -F "$fn" > /dev/null; then
        "$fn" "$@"
    fi
}

service_compose_file() {
    local file
    file=$(run_service_hook "$1" compose_file)
    echo "${file:-$(service_dir "$1")/compose.yaml}"
}

# Name of the service owning a compose file (empty if none)
service_name_for_file() {
    local name
    for name in $(service_names); do
        [ "$(service_compose_file "$name")" = "$1" ] && echo "$name" && return 0
    done
}

# Every compose file of the stack, in start order
compose_files() {
    local name
    for name in $(service_names); do
        service_compose_file "$name"
    done
}

compose_files_reversed() {
    compose_files | tac
}

# Run "docker compose -f <file> <args...>" on every existing compose file.
# --reverse goes from the last service down to the first (for stop/down).
compose_each() {
    local order=compose_files
    if [ "$1" = "--reverse" ]; then
        order="compose_files_reversed"
        shift
    fi

    local file
    # fd 3: docker compose must not read the file list from stdin
    while read -r file <&3; do
        [ -f "$file" ] || continue
        docker compose -f "$file" "$@"
    done 3< <($order)
}

# Returns 0 if at least one container of the project is running
project_is_running() {
    [ -n "$(docker ps -q --filter "label=com.docker.compose.project=$COMPOSE_PROJECT_NAME")" ]
}

competition.sh_setup_command() {

  log_section "Installing Dependencies"

  # Detect OS
  if [ -f /etc/os-release ]; then
      . /etc/os-release
      OS=$NAME
      VERSION_CODENAME=${VERSION_CODENAME:-$(echo $VERSION | cut -d' ' -f1)}
  else
      log_error "Cannot detect OS"
      exit 1
  fi

  log_info "Detected OS: $OS"

  # Update package manager
  log_subsection "Updating Package Manager"
  apt update
  log_success "Package manager updated"

  # Install basic dependencies
  log_subsection "Installing Basic Dependencies"
  basic_deps="ca-certificates curl git sudo wget apt-transport-https gnupg lsb-release"
  apt install -y $basic_deps
  log_success "Basic dependencies installed"

  # Install jq for JSON parsing
  log_subsection "Installing jq"
  apt install -y jq
  log_success "jq installed"

  # Install Docker
  log_subsection "Installing Docker"

  # Add Docker's official GPG key
  log_info "Adding Docker GPG key..."
  install -m 0755 -d /etc/apt/keyrings
  curl -fsSL https://download.docker.com/linux/debian/gpg -o /etc/apt/keyrings/docker.asc
  chmod a+r /etc/apt/keyrings/docker.asc
  log_debug "Docker GPG key added"

  # Add the repository to Apt sources
  log_info "Adding Docker repository..."
  echo \
    "deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/debian \
    $(. /etc/os-release && echo "$VERSION_CODENAME") stable" | \
    tee /etc/apt/sources.list.d/docker.list > /dev/null
  apt update
  log_debug "Docker repository added"

  # Install Docker packages
  log_info "Installing Docker packages..."
  apt install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
  log_success "Docker installed"

  # Setup Docker daemon
  log_subsection "Configuring Docker"
  systemctl enable docker
  systemctl start docker
  log_success "Docker daemon configured and started"

  # Add current user to docker group (if not running as root)
  if [ -n "$SUDO_USER" ]; then
      log_info "Adding $SUDO_USER to docker group..."
      usermod -aG docker "$SUDO_USER"
      log_success "$SUDO_USER added to docker group (may require logout/login)"
  fi

  # Install certbot for Let's Encrypt (optional but recommended)
  log_subsection "Installing Certbot (Let's Encrypt)"
  apt install -y certbot python3-certbot-dns-route53 || apt install -y certbot
  log_success "Certbot installed"

  # Install btop for system monitoring (optional but useful)
  log_subsection "Installing System Tools"
  apt install -y btop net-tools
  log_success "System tools installed"

  # Verify installations
  log_section "Verifying Installations"

  check_command() {
      if command -v "$1" &> /dev/null; then
          version=$($1 --version 2>&1 | head -n1)
          log_success "$1 installed: $version"
          return 0
      else
          log_error "$1 not found"
          return 1
      fi
  }

  check_command "docker"
  check_command "jq"
  check_command "git"
  check_command "curl"
  check_command "wget"

  # Verify docker daemon is running
  if docker ps > /dev/null 2>&1; then
      log_success "Docker daemon is running"
  else
      log_warning "Docker daemon may not be running. Try: sudo systemctl start docker"
  fi

  echo ""
  log_success "All dependencies installed successfully! 🎉"
  echo ""
  log_info "Next steps:"
  echo "  1. Review config/main.json and customize settings"
  echo "  2. Run: sudo ./competition.sh init"
  echo ""

}

competition.sh_check_config_command() {

  errors=$(validate_configuration)

  if [ -n "$errors" ]; then
      log_error "Invalid config/main.json:"
      sed 's/^/  - /' <<< "$errors" >&2
      exit 1
  fi
  log_success "config/main.json is valid"

}

competition.sh_init_command() {

  initialize_configuration

  # Each service: prepare (pre_init), start, wait until it answers, configure (post_init).
  # Order matters: gitea's post_init creates the runner token, the API token and the registry login
  # used by the runners and competitors services after it.
  for name in $(service_names); do
      log_section "Service: $name"
      run_service_hook "$name" pre_init
      run_service_hook "$name" pre_up
      compose_file=$(service_compose_file "$name")
      # pre_init may decide there is nothing to start (e.g. no API enabled)
      if [ ! -f "$compose_file" ]; then
          log_info "Nothing to start"
          continue
      fi
      docker compose -f "$compose_file" up -d
      run_service_hook "$name" wait_ready
      run_service_hook "$name" post_init
  done

  export_environment_variables "$BASE_DIR/.env"

  echo ""
  log_success "All done! Competition environment is ready! 🎉"

}

competition.sh_start_command() {

  log_section "Starting Services"
  compose_each start
  log_success "Services started"

}

competition.sh_stop_command() {

  log_section "Stopping Services"
  compose_each --reverse stop
  log_success "Services stopped"

}

competition.sh_recreate_command() {

  eval "targets=(${args[service]})"

  build_service_map

  if [ ${#targets[@]} -eq 0 ]; then
      print_available
      exit 0
  fi

  for target in "${targets[@]}"; do
      if [ -z "${SERVICE_FILE[$target]}" ] && [ -z "${GROUP_FILE[$target]}" ]; then
          log_error "Unknown service or group: $target"
          echo ""
          print_available
          exit 1
      fi
  done

  log_section "Recreating Services"
  had_failure=0
  for target in "${targets[@]}"; do
      if [ -n "${SERVICE_FILE[$target]}" ]; then
          recreate_service "${SERVICE_FILE[$target]}" "$target" || had_failure=1
      else
          file=${GROUP_FILE[$target]}
          for svc in $(docker compose -f "$file" config --services); do
              recreate_service "$file" "$svc" || had_failure=1
          done
      fi
  done

  if [ "$had_failure" -ne 0 ]; then
      log_error "Some services failed to be recreated"
      exit 1
  fi
  log_success "Done"

}

competition.sh_import_frameworks_command() {

  # Reads frameworks_repo and allowed_frameworks from config/main.json:
  #   - existing templates get a new "Update framework" commit (history and links from generated repos kept)
  #   - newly allowed frameworks are created
  #   - frameworks removed from allowed_frameworks are left untouched in Gitea
  load_configuration
  setup_protocol_vars
  setup_service_vars
  setup_directory_vars

  wait_for_gitea

  load_personal_access_token "$BASE_DIR/.env" || exit 1

  import_all_frameworks

  # New templates may need new npm packages (npmjs is cut off by default)
  log_section "Prefetching npm packages"
  prefetch_npm_packages

}

competition.sh_prefetch_npm_command() {

  # Also run by init (post_init of the verdaccio service) and import-frameworks
  log_section "Prefetching npm packages"
  if [[ ${args[--keep-online]} ]]; then
      prefetch_npm_packages --keep-online
  else
      prefetch_npm_packages
  fi

}

competition.sh_npm_proxy_command() {

  mode=${args[mode]}

  if [ -z "$mode" ]; then
      echo "npm proxy: $(verdaccio_proxy_mode)"
      exit 0
  fi

  write_verdaccio_config "$mode"
  restart_verdaccio
  if [ "$mode" = on ]; then
      log_success "npm proxy on: competitors can install any npm package (fetched from npmjs and cached)"
  else
      log_success "npm proxy off: only the packages cached in data/verdaccio can be installed"
  fi

}

competition.sh_deploy_apis_command() {

  # Can be run at any time: existing SQLite copies are kept, only changed containers are recreated.
  # Code changes need no deploy at all, the code is mounted read-only in the containers.
  log_section "Deploying APIs"
  load_configuration
  setup_protocol_vars

  service_apis_pre_init

  compose_file=$(service_apis_compose_file)
  remove_stale_api_containers "$compose_file"

  # The portal shows each competitor's API URLs (read at every request, no restart needed)
  declare -F write_portal_config > /dev/null && write_portal_config

  if [ -f "$compose_file" ]; then
      docker compose -f "$compose_file" up -d
      log_success "APIs deployed"
  else
      log_warning "No API enabled in config/apis/ (set \"enabled\": true in an api.json)"
  fi

}

competition.sh_reset_api_command() {

  name=${args[api]}
  competitor=${args[competitor]}

  dir=$(api_dir_by_name "$name") || { log_error "No enabled API named \"$name\""; exit 1; }
  if [ -z "$(api_field "$dir" '.sqlite // empty')" ]; then
      log_error "API \"$name\" has no SQLite database (no \"sqlite\" in its api.json)"
      exit 1
  fi
  if [ -n "$competitor" ] && ! jq -e --arg u "$competitor" '.competitors | any(.username == $u)' "$CONFIG_DIR/main.json" > /dev/null; then
      log_error "Unknown competitor: $competitor"
      exit 1
  fi

  log_section "Resetting API $name"
  if [ -n "$competitor" ]; then
      containers=("${competitor}_${name}")
  else
      mapfile -t containers < <(jq -r --arg n "$name" '.competitors[] | "\(.username)_\($n)"' "$CONFIG_DIR/main.json")
  fi

  # Stopped while the database is replaced, so no request writes to the old one
  docker stop "${containers[@]}" > /dev/null 2>&1
  prepare_api_data "$dir" "$competitor" true
  docker start "${containers[@]}" > /dev/null
  log_success "Database reset for: ${containers[*]}"

}

competition.sh_backup_command() {

  # Services are stopped during the copy so the MySQL files are consistent, then started again
  log_section "Backing up Competition Environment"

  was_running=false
  if project_is_running; then
      was_running=true
      log_subsection "Stopping services for a consistent copy"
      compose_each --reverse stop
  fi

  log_subsection "Archiving"
  create_backup_archive "manual"
  status=$?

  if [ "$was_running" = true ]; then
      log_subsection "Starting services again"
      compose_each start
  fi

  exit $status

}

competition.sh_restore_command() {

  # The current environment is cleaned first, which itself creates a backup of it
  if [ -z "${args[backup]}" ]; then
      list_backups
      exit 0
  fi

  archive=$(resolve_backup "${args[backup]}")
  if [ -z "$archive" ]; then
      log_error "Backup not found: ${args[backup]}"
      echo ""
      list_backups
      exit 1
  fi

  log_section "Restoring $(basename "$archive")"

  log_subsection "Checking archive"
  contents=$(tar -tzf "$archive" 2>/dev/null) || { log_error "Archive is corrupted or unreadable"; exit 1; }
  if ! grep -q '^data/' <<< "$contents" || ! grep -qx '.env' <<< "$contents"; then
      log_error "This archive does not look like a competition backup (missing data/ or .env)"
      exit 1
  fi
  log_success "Archive OK"

  clean_environment true

  log_section "Extracting Backup"
  run_with_spinner "Extracting $(basename "$archive")..." \
      tar --numeric-owner -xzpf "$archive" -C "$BASE_DIR" || exit 1

  touch "$LOCK_FILE"
  log_success "Files restored"

  load_env_file

  log_section "Starting Services"
  # Competitor images are pulled from Gitea's registry: each service waits for the previous ones
  for name in $(service_names); do
      compose_file=$(service_compose_file "$name")
      [ -f "$compose_file" ] || continue
      log_subsection "$name"
      run_service_hook "$name" pre_up
      docker compose -f "$compose_file" up -d < /dev/null
      run_service_hook "$name" wait_ready
  done

  echo ""
  log_success "Restore complete! 🎉"

}

competition.sh_clean_command() {

  if [[ ${args[--no-backup]} ]]; then
      clean_environment false
  else
      clean_environment true
  fi

}

parse_requirements() {
  local key

  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
      --version)
        version_command
        exit
        ;;

      --help | -h)
        long_usage=yes
        competition.sh_usage
        exit
        ;;

      --verbose | -v)

        args['--verbose']=1
        shift
        ;;

      *)
        break
        ;;

    esac
  done

  action=${1:-}

  case $action in
    -*) ;;

    setup)
      action="setup"
      shift
      competition.sh_setup_parse_requirements "$@"
      shift $#
      ;;

    check-config)
      action="check-config"
      shift
      competition.sh_check_config_parse_requirements "$@"
      shift $#
      ;;

    init)
      action="init"
      shift
      competition.sh_init_parse_requirements "$@"
      shift $#
      ;;

    start)
      action="start"
      shift
      competition.sh_start_parse_requirements "$@"
      shift $#
      ;;

    stop)
      action="stop"
      shift
      competition.sh_stop_parse_requirements "$@"
      shift $#
      ;;

    recreate)
      action="recreate"
      shift
      competition.sh_recreate_parse_requirements "$@"
      shift $#
      ;;

    import-frameworks)
      action="import-frameworks"
      shift
      competition.sh_import_frameworks_parse_requirements "$@"
      shift $#
      ;;

    prefetch-npm)
      action="prefetch-npm"
      shift
      competition.sh_prefetch_npm_parse_requirements "$@"
      shift $#
      ;;

    npm-proxy)
      action="npm-proxy"
      shift
      competition.sh_npm_proxy_parse_requirements "$@"
      shift $#
      ;;

    deploy-apis)
      action="deploy-apis"
      shift
      competition.sh_deploy_apis_parse_requirements "$@"
      shift $#
      ;;

    reset-api)
      action="reset-api"
      shift
      competition.sh_reset_api_parse_requirements "$@"
      shift $#
      ;;

    backup)
      action="backup"
      shift
      competition.sh_backup_parse_requirements "$@"
      shift $#
      ;;

    restore)
      action="restore"
      shift
      competition.sh_restore_parse_requirements "$@"
      shift $#
      ;;

    clean)
      action="clean"
      shift
      competition.sh_clean_parse_requirements "$@"
      shift $#
      ;;

    "")
      competition.sh_usage >&2
      exit 1
      ;;

    *)
      printf "invalid command: %s\n" "$action" >&2
      exit 1
      ;;

  esac

  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in

      --)
        shift
        while [[ $# -gt 0 ]]; do
          key="$1"

          printf "invalid argument: %s\n" "$key" >&2
          exit 1

        done
        break
        ;;

      -?*)
        printf "invalid option: %s\n" "$key" >&2
        exit 1
        ;;

      *)

        printf "invalid argument: %s\n" "$key" >&2
        exit 1

        ;;

    esac
  done

}

competition.sh_setup_parse_requirements() {
  local key

  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
      --help | -h)
        long_usage=yes
        competition.sh_setup_usage
        exit
        ;;

      *)
        break
        ;;

    esac
  done

  action="setup"

  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in

      --)
        shift
        while [[ $# -gt 0 ]]; do
          key="$1"

          printf "invalid argument: %s\n" "$key" >&2
          exit 1

        done
        break
        ;;

      -?*)
        printf "invalid option: %s\n" "$key" >&2
        exit 1
        ;;

      *)

        printf "invalid argument: %s\n" "$key" >&2
        exit 1

        ;;

    esac
  done

  filter_error=$(filter_root)
  if [[ -n $filter_error ]]; then
    echo "$filter_error" >&2
    exit 1
  fi

}

competition.sh_check_config_parse_requirements() {
  local key

  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
